const auto = $('Automation KPIs').first().json || {};
const out = $('Outreach KPIs').first().json || {};
const events = $('Last 24h Events').first().json || {};

const briefing = [
  '# Daily CEO Briefing',
  `Date: ${new Date().toISOString().split('T')[0]}`,
  '',
  '## System Health',
  `- Heartbeat success: ${((auto.heartbeat_success_rate || 0) * 100).toFixed(0)}%`,
  `- Override rate: ${((auto.override_rate || 0) * 100).toFixed(0)}%`,
  `- Events (24h): ${events.total || 0}`,
  `- Policy violations (24h): ${events.violations || 0}`,
  '',
  '## Pipeline (this week)',
  `- Drafts: ${out.drafts || 0}`,
  `- Sent: ${out.sent || 0}`,
  `- Responses: ${out.responses || 0}`,
  `- Response rate: ${((out.response_rate || 0) * 100).toFixed(1)}%`,
  '',
  '## Flags',
];

const flags = [];
if ((auto.heartbeat_success_rate || 0) < 0.8) flags.push('Heartbeat success below 80%');
if ((auto.override_rate || 0) > 0.25) flags.push('Override rate above 25%');
if ((events.violations || 0) > 0) flags.push(`${events.violations} policy violations in 24h`);
if ((out.negative_rate || 0) > 0.05) flags.push('Negative reply rate above 5%');

if (flags.length === 0) briefing.push('- No strategic flags.');
else flags.forEach(f => briefing.push(`- !! ${f}`));

return [{json: {briefing: briefing.join('\n'), has_flags: flags.length > 0, flag_count: flags.length}}];
